import{_ as a,c as e,o as n,a3 as i}from"./chunks/framework.Cc9k46oU.js";const g=JSON.parse('{"title":"スクラムバン（Scrumban）フェーズ別Activity","description":"スクラムバン（Scrumban）は、スクラムの反復的な構造とカンバンのフロー管理・WIP制限を組み合わせ、柔軟かつ効率的に作業を管理するハイブリッドアジャイル手法です。","frontmatter":{"title":"スクラムバン（Scrumban）フェーズ別Activity","description":"スクラムバン（Scrumban）は、スクラムの反復的な構造とカンバンのフロー管理・WIP制限を組み合わせ、柔軟かつ効率的に作業を管理するハイブリッドアジャイル手法です。","head":[["meta",{"name":"keywords","content":"スクラムバン, Scrumban, スクラムバン紹介, スクラムバン概念, スクラムバンとは, Scrumban紹介, Scrumban概念, スクラムとカンバンの違い, スクラム vs カンバン, アジャイル手法, アジャイルフレームワーク, カンバン手法, スクラム手法, スクラムバンプロセス, スクラムバン運用ガイド, スクラムバンボード, WIP制限, 作業フロー管理, カンバンボードの使い方, スクラムバンのメリット, スクラムバンの特徴, スクラムバンの効果, スクラムバン活用事例, スクラムバン導入効果, スクラムバンJira設定, スクラムバンボードテンプレート, Scrumbanツール, スクラムバンコラボレーションツール, スクラムバンワークフロー, アジャイルプロジェクト管理, 業務効率化手法, 反復作業管理, ボトルネック解消"}],["meta",{"property":"og:title","content":"スクラムバン"}],["meta",{"property":"og:description","content":"スクラムバン（Scrumban）は、スクラムの反復的な構造とカンバンのフロー管理・WIP制限を組み合わせ、柔軟かつ効率的に作業を管理するハイブリッドアジャイル手法です。"}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/ja/agile/activity"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/ja/agile/activity"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/agile/activity"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/agile/activity"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/agile/activity"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/agile/activity"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"Empasy Docs"}],["meta",{"property":"og:title","content":"スクラムバン（Scrumban）フェーズ別Activity | Empasy Docs"}],["meta",{"property":"og:description","content":"スクラムバン（Scrumban）は、スクラムの反復的な構造とカンバンのフロー管理・WIP制限を組み合わせ、柔軟かつ効率的に作業を管理するハイブリッドアジャイル手法です。"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/ja/agile/activity"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"スクラムバン（Scrumban）フェーズ別Activity | Empasy Docs"}],["meta",{"name":"twitter:description","content":"スクラムバン（Scrumban）は、スクラムの反復的な構造とカンバンのフロー管理・WIP制限を組み合わせ、柔軟かつ効率的に作業を管理するハイブリッドアジャイル手法です。"}]],"sort":400},"headers":[],"relativePath":"ja/agile/activity.md","filePath":"ja/agile/activity.md","lastUpdated":1795293539000}'),r={name:"ja/agile/activity.md"};function s(l,t,o,d,c,p){return n(),e("div",null,[...t[0]||(t[0]=[i(`<h1 id="スクラムバン-フェーズ別activityガイド" tabindex="-1">スクラムバン フェーズ別Activityガイド <a class="header-anchor" href="#スクラムバン-フェーズ別activityガイド" aria-label="Permalink to “スクラムバン フェーズ別Activityガイド”">​</a></h1><table tabindex="0"><thead><tr><th>フェーズ</th><th>主なActivity</th><th>詳細説明</th></tr></thead><tbody><tr><td><strong>1. Backlog</strong></td><td>- 新規アイデア・リクエストの収集<br>- バックログアイテムの記録<br>- サービスクラス（Class of Service）の指定</td><td>すべての作業の出発点です。<br>ビジネス要求、バグ、技術的負債などを<strong>Product Owner</strong>やチームが記録します。<br>各カードに<strong>優先度</strong>と<strong>作業タイプ（緊急・期日固定・標準・無形）</strong>を指定します。<br>このフェーズでは、まだ着手の準備が整っていない状態です。</td></tr><tr><td><strong>2. Ready</strong></td><td>- Definition of Ready (DoR) の確認<br>- 作業の分解（必要時）<br>- 担当者未指定</td><td>作業をすぐ開始できるよう詳細内容が整った状態です。<br>DoR基準（要件の明確化、デザイン・リソースの確保、テスト条件の定義など）を満たす必要があります。<br>通常、<strong>Replenishmentミーティング</strong>でBacklogからReadyへ移動します。</td></tr><tr><td><strong>3. Doing / In Progress</strong></td><td>- 作業開始（Pull）<br>- 進行状況のアップデート<br>- ブロッカーの明示</td><td>チームメンバーがWIP上限内でReadyからPullして作業を開始します。<br>作業中に発生した<strong>ボトルネック・ブロッカー</strong>は、ボード上で視覚的に表示します（赤いラベル、アイコンなど）。<br>デイリースタンドアップでステータスを共有します。</td></tr><tr><td><strong>4. Review (Code Review / Peer Review)</strong></td><td>- コードレビュー・ドキュメントレビューの実施<br>- フィードバックの反映</td><td>開発が完了した作業はReviewカラムへ移動します。<br>指定されたレビュアーがコード品質や標準への準拠を確認します。<br>レビューのフィードバックがある場合はDoingへ戻すか、修正後に再度Reviewフェーズへ進めます。</td></tr><tr><td><strong>5. Testing / QA</strong></td><td>- 機能テスト<br>- バグレポートの作成および修正</td><td>QAまたはチームメンバーがテストを実施します。<br>自動テストと手動テストを併用できます。<br>バグが見つかった場合は該当カードに記録し、修正後に再検証を行います。</td></tr><tr><td><strong>6. Done</strong></td><td>- Definition of Done (DoD) の充足確認<br>- ドキュメント・リリースノートの更新<br>- デプロイ完了</td><td>すべての品質基準を満たし、デプロイまで完了した状態です。<br>リリースノートやユーザーマニュアルなどのドキュメント化を含みます。<br>カードに完了日を記録します（サイクルタイム分析に活用）。</td></tr></tbody></table><hr><h2 id="各フェーズのactivityフロー可視化" tabindex="-1">各フェーズのActivityフロー可視化 <a class="header-anchor" href="#各フェーズのactivityフロー可視化" aria-label="Permalink to “各フェーズのActivityフロー可視化”">​</a></h2><div class="language-"><button title="コードをコピー" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Backlog]</span></span>
<span class="line"><span>  ↓ (Replenishmentミーティング)</span></span>
<span class="line"><span>[Ready]</span></span>
<span class="line"><span>  ↓ (Pull &amp; WIPチェック)</span></span>
<span class="line"><span>[Doing]</span></span>
<span class="line"><span>  ↓ (開発完了)</span></span>
<span class="line"><span>[Review]</span></span>
<span class="line"><span>  ↓ (レビュー承認)</span></span>
<span class="line"><span>[Testing]</span></span>
<span class="line"><span>  ↓ (品質検証完了)</span></span>
<span class="line"><span>[Done]</span></span></code></pre></div><hr><h2 id="フェーズ別運用ヒント" tabindex="-1">フェーズ別運用ヒント <a class="header-anchor" href="#フェーズ別運用ヒント" aria-label="Permalink to “フェーズ別運用ヒント”">​</a></h2><h3 id="_1-backlog" tabindex="-1">1. Backlog <a class="header-anchor" href="#_1-backlog" aria-label="Permalink to “1. Backlog”">​</a></h3><ul><li><strong>優先度基準の明確化</strong>: 緊急度、ビジネス価値、期限、リスクに基づく判断</li><li><strong>カードサイズの標準化</strong>: 大きすぎる場合はReadyへ移す前に分割</li><li><strong>定期的な整理</strong>: 古いカードや不要になったカードは破棄</li></ul><h3 id="_2-ready" tabindex="-1">2. Ready <a class="header-anchor" href="#_2-ready" aria-label="Permalink to “2. Ready”">​</a></h3><ul><li><p><strong>作業着手可能条件（DoR）チェックリスト例</strong></p><ul><li>要件が明確である</li><li>デザイン・データ・リソースが確保されている</li><li>テスト条件が定義されている</li><li>見積もり作業時間・スコープが確認されている</li></ul></li></ul><h3 id="_3-doing" tabindex="-1">3. Doing <a class="header-anchor" href="#_3-doing" aria-label="Permalink to “3. Doing”">​</a></h3><ul><li><strong>Stop Starting, Start Finishing</strong> ルールの維持</li><li>ボトルネック発生時は即座に解決策を協議</li><li>マルチタスクの最小化</li></ul><h3 id="_4-review" tabindex="-1">4. Review <a class="header-anchor" href="#_4-review" aria-label="Permalink to “4. Review”">​</a></h3><ul><li>コードレビュー基準の定義（例：コードスタイル、パフォーマンス、セキュリティ、テストの有無）</li><li>レビュー待ち時間を短縮するための通知システムの活用</li></ul><h3 id="_5-testing" tabindex="-1">5. Testing <a class="header-anchor" href="#_5-testing" aria-label="Permalink to “5. Testing”">​</a></h3><ul><li>自動テストと手動テストの併用</li><li>バグ発生時は同一カード上で修正後に再検証</li><li>テスト失敗時はWIP超過の例外を許容可能</li></ul><h3 id="_6-done" tabindex="-1">6. Done <a class="header-anchor" href="#_6-done" aria-label="Permalink to “6. Done”">​</a></h3><ul><li>完了後にカードへ<strong>サイクルタイムを記録</strong></li><li>リリースふりかえり時に完了カードをレビュー</li><li>データ分析用タグ（バグ、新機能など）を付与</li></ul><hr><h2 id="フェーズ別主要指標" tabindex="-1">フェーズ別主要指標 <a class="header-anchor" href="#フェーズ別主要指標" aria-label="Permalink to “フェーズ別主要指標”">​</a></h2><table tabindex="0"><thead><tr><th>フェーズ</th><th>主要指標</th><th>活用目的</th></tr></thead><tbody><tr><td>Backlog → Ready</td><td>リードタイム（要求~準備完了）</td><td>準備遅延の原因把握</td></tr><tr><td>Ready → Doing</td><td>Pull頻度</td><td>チームの処理能力の把握</td></tr><tr><td>Doing</td><td>平均WIP、ブロッカー比率</td><td>ボトルネック管理</td></tr><tr><td>Review</td><td>レビュー待ち時間</td><td>品質と速度のバランス調整</td></tr><tr><td>Testing</td><td>欠陥率、手戻り率</td><td>QA効率性の評価</td></tr><tr><td>Done</td><td>サイクルタイム、スループット</td><td>予測可能性の向上</td></tr></tbody></table><hr><p>このように整理することで、<strong>スクラムバンを導入したチームが各フェーズで何を実施すべきか</strong>が明確になり、 <strong>メトリクスに基づく継続的改善活動</strong>もあわせて推進できます。</p><hr>`,25)])])}const m=a(r,[["render",s]]);export{g as __pageData,m as default};
